// Local modifications:
// - Place spawned processes in a Job Object so kill operations terminate the
//   full process tree, while normal root exit preserves background descendants.

use anyhow::Context as _;
use filedescriptor::OwnedHandle;
use portable_pty::Child;
use portable_pty::ChildKiller;
use portable_pty::ExitStatus;
use std::io::Error as IoError;
use std::io::Result as IoResult;
use std::os::windows::io::AsRawHandle;
use std::pin::Pin;
use std::sync::Arc;
use std::sync::Mutex;
use std::task::Context;
use std::task::Poll;
use winapi::shared::minwindef::DWORD;
use winapi::shared::winerror::WAIT_TIMEOUT;
use winapi::um::processthreadsapi::*;
use winapi::um::synchapi::WaitForSingleObject;
use winapi::um::winbase::INFINITE;
use winapi::um::winbase::WAIT_FAILED;
use winapi::um::winbase::WAIT_OBJECT_0;

pub(crate) mod conpty;
mod job;
mod procthreadattr;
mod psuedocon;

pub use conpty::ConPtySystem;
pub use job::JobObject;
pub use psuedocon::PsuedoCon;
pub use psuedocon::conpty_supported;

#[derive(Debug)]
pub struct WinChild {
    proc: Mutex<OwnedHandle>,
    job: Arc<JobObject>,
}

impl WinChild {
    pub(crate) fn new(proc: OwnedHandle, job: Arc<JobObject>) -> Self {
        Self {
            proc: Mutex::new(proc),
            job,
        }
    }

    fn is_complete(&mut self) -> IoResult<Option<ExitStatus>> {
        self.observe_exit(/*wait_ms*/ 0)
    }

    fn observe_exit(&self, wait_ms: DWORD) -> IoResult<Option<ExitStatus>> {
        let proc = self
            .proc
            .lock()
            .map_err(|_| IoError::other("ConPTY process handle lock poisoned"))?
            .try_clone()
            .map_err(|error| match error {
                filedescriptor::Error::Io(error) => error,
                error => IoError::other(error),
            })?;
        match unsafe { WaitForSingleObject(proc.as_raw_handle() as _, wait_ms) } {
            WAIT_OBJECT_0 => {
                let mut status: DWORD = 0;
                if unsafe { GetExitCodeProcess(proc.as_raw_handle() as _, &mut status) } == 0 {
                    return Err(IoError::last_os_error());
                }
                // The native object is signaled. A numeric 259 is now an actual
                // exit code, rather than an inference from STILL_ACTIVE alone.
                self.preserve_descendants();
                Ok(Some(ExitStatus::with_exit_code(status)))
            }
            WAIT_TIMEOUT => Ok(None),
            WAIT_FAILED => Err(IoError::last_os_error()),
            _ => Err(IoError::other("unexpected ConPTY process wait result")),
        }
    }

    fn do_kill(&mut self) -> IoResult<()> {
        self.job.terminate()
    }

    fn preserve_descendants(&self) {
        if let Err(err) = self.job.preserve_descendants() {
            log::warn!("ConPTY failed to preserve descendants after root exit: {err}");
        }
    }
}

impl ChildKiller for WinChild {
    fn kill(&mut self) -> IoResult<()> {
        if let Err(err) = self.do_kill() {
            log::warn!("ConPTY failed to terminate process tree: {err}");
        }
        Ok(())
    }

    fn clone_killer(&self) -> Box<dyn ChildKiller + Send + Sync> {
        Box::new(WinChildKiller {
            job: Arc::clone(&self.job),
        })
    }
}

#[derive(Debug)]
pub struct WinChildKiller {
    job: Arc<JobObject>,
}

impl ChildKiller for WinChildKiller {
    fn kill(&mut self) -> IoResult<()> {
        self.job.terminate()
    }

    fn clone_killer(&self) -> Box<dyn ChildKiller + Send + Sync> {
        Box::new(WinChildKiller {
            job: Arc::clone(&self.job),
        })
    }
}

impl Child for WinChild {
    fn try_wait(&mut self) -> IoResult<Option<ExitStatus>> {
        self.is_complete()
    }

    fn wait(&mut self) -> IoResult<ExitStatus> {
        if let Some(status) = self.try_wait()? {
            return Ok(status);
        }
        self.observe_exit(INFINITE)?.ok_or_else(|| {
            IoError::other("infinite ConPTY wait returned without terminal evidence")
        })
    }

    fn process_id(&self) -> Option<u32> {
        let res = unsafe { GetProcessId(self.proc.lock().unwrap().as_raw_handle() as _) };
        if res == 0 { None } else { Some(res) }
    }

    fn as_raw_handle(&self) -> Option<std::os::windows::io::RawHandle> {
        let proc = self.proc.lock().unwrap();
        Some(proc.as_raw_handle())
    }
}

#[cfg(test)]
#[path = "native_observation_tests.rs"]
mod observation_tests;

impl std::future::Future for WinChild {
    type Output = anyhow::Result<ExitStatus>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context) -> Poll<anyhow::Result<ExitStatus>> {
        match self.is_complete() {
            Ok(Some(status)) => Poll::Ready(Ok(status)),
            Err(err) => Poll::Ready(Err(err).context("Failed to retrieve process exit status")),
            Ok(None) => {
                let proc = self.proc.lock().unwrap().try_clone()?;
                let waker = cx.waker().clone();
                std::thread::spawn(move || {
                    unsafe {
                        WaitForSingleObject(proc.as_raw_handle() as _, INFINITE);
                    }
                    waker.wake();
                });
                Poll::Pending
            }
        }
    }
}

//! Unified exec session spawner for Windows sandboxing.
//!
//! This module is the thin orchestration layer for Windows unified-exec sessions.
//! Backend-specific mechanics live in sibling modules:
//! - `backends::legacy` adapts the direct restricted-token spawn path into a live session.
//! - `backends::elevated` adapts the elevated command-runner IPC path into the same session API.
//! - `backends::windows_common` holds the small shared Windows backend helpers
//!   used by both.

mod backends;

use crate::resolved_permissions::ResolvedWindowsSandboxPermissions;
use anyhow::Result;
use anyhow::bail;
use codex_protocol::config_types::WindowsSandboxLevel;
use codex_protocol::models::PermissionProfile;
use codex_utils_absolute_path::AbsolutePathBuf;
use codex_utils_pty::SpawnedProcess;
use std::collections::HashMap;
use std::path::Path;
use std::path::PathBuf;

/// Fully resolved Windows sandbox session launch request.
///
/// Callers should parse their own input shape first, then use this request to
/// share the elevated-vs-legacy backend selection and session launch path.
pub struct WindowsSandboxSessionRequest<'a> {
    pub permission_profile: &'a PermissionProfile,
    pub workspace_roots: &'a [AbsolutePathBuf],
    pub codex_home: &'a Path,
    pub command: Vec<String>,
    pub cwd: &'a Path,
    pub env_map: HashMap<String, String>,
    pub windows_sandbox_level: WindowsSandboxLevel,
    pub proxy_enforced: bool,
    pub network_proxy_restricting_sid: Option<String>,
    pub proxy_settings_mode: crate::WindowsSandboxProxySettingsMode,
    pub timeout_ms: Option<u64>,
    pub read_roots_override: Option<&'a [PathBuf]>,
    pub read_roots_include_platform_defaults: bool,
    pub write_roots_override: Option<&'a [PathBuf]>,
    pub deny_read_paths_override: &'a [AbsolutePathBuf],
    pub deny_write_paths_override: &'a [AbsolutePathBuf],
    pub tty: bool,
    pub stdin_open: bool,
    pub use_private_desktop: bool,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum WindowsSandboxBackend {
    RestrictedToken,
    Elevated,
}

/// Select the only backend that can enforce the requested filesystem policy.
///
/// A `WRITE_RESTRICTED` token limits ordinary write access through restricting
/// SIDs, but Windows can authorize deletion through a parent directory's
/// `FILE_DELETE_CHILD` right. That alternate authorization path means the
/// restricted-token backend cannot prove that deletion stays inside the
/// declared writable roots. Explicit filesystem overrides have the same
/// problem because their effective parent ACLs are not part of the token.
///
/// Explicit Elevated requests use the broker's separate provisioning path. The
/// public entry refuses RestrictedToken requests before this selector, including
/// profiles this mapping would otherwise redirect to the broker. Disabled is an
/// invalid level for this sandbox-session API; ordinary disabled execution uses
/// SandboxType::None outside it. Neither backend selection nor a read-only profile
/// qualifies a deletion boundary under ambient parent rights. There is no fallback
/// from a failed backend to unrestricted execution.
fn select_windows_sandbox_backend(
    request: &WindowsSandboxSessionRequest<'_>,
) -> Result<WindowsSandboxBackend> {
    if matches!(request.windows_sandbox_level, WindowsSandboxLevel::Elevated) {
        return Ok(WindowsSandboxBackend::Elevated);
    }
    if request.proxy_enforced {
        bail!("managed networking requires the elevated Windows sandbox backend");
    }
    if request.network_proxy_restricting_sid.is_some() {
        bail!("network proxy restricting SID requires the elevated Windows sandbox backend");
    }

    let permissions =
        ResolvedWindowsSandboxPermissions::try_from_permission_profile_for_workspace_roots(
            request.permission_profile,
            request.workspace_roots,
        )?;
    let requires_elevated_filesystem = !permissions.has_full_disk_read_access()
        || permissions.uses_write_capabilities_for_cwd(request.cwd, &request.env_map)
        || request.read_roots_override.is_some()
        || request.write_roots_override.is_some()
        || !request.deny_read_paths_override.is_empty()
        || !request.deny_write_paths_override.is_empty();

    Ok(if requires_elevated_filesystem {
        WindowsSandboxBackend::Elevated
    } else {
        WindowsSandboxBackend::RestrictedToken
    })
}

pub async fn spawn_windows_sandbox_session_for_level(
    request: WindowsSandboxSessionRequest<'_>,
) -> Result<SpawnedProcess> {
    match request.windows_sandbox_level {
        WindowsSandboxLevel::RestrictedToken => {
            // Refuse before the selector can turn a requested legacy workspace
            // or override into broker provisioning.
            crate::legacy_admission::require_legacy_filesystem_isolation()?;
        }
        // Explicit Elevated is a separate entry with its own identity and native
        // qualification requirements. It is not a fallback for a legacy request.
        WindowsSandboxLevel::Elevated => {}
        WindowsSandboxLevel::Disabled => {
            bail!("disabled Windows sandbox level cannot launch a sandbox session");
        }
    }
    match select_windows_sandbox_backend(&request)? {
        WindowsSandboxBackend::Elevated => {
            backends::elevated::spawn_windows_sandbox_session_elevated_for_permission_profile(
                request.permission_profile,
                request.workspace_roots,
                request.codex_home,
                request.command,
                request.cwd,
                request.env_map,
                request.proxy_enforced,
                request.network_proxy_restricting_sid,
                request.proxy_settings_mode,
                request.timeout_ms,
                request.read_roots_override,
                request.read_roots_include_platform_defaults,
                request.write_roots_override,
                request.deny_read_paths_override,
                request.deny_write_paths_override,
                request.tty,
                request.stdin_open,
                request.use_private_desktop,
            )
            .await
        }
        WindowsSandboxBackend::RestrictedToken => {
            spawn_windows_sandbox_session_legacy(
                request.permission_profile,
                request.workspace_roots,
                request.codex_home,
                request.command,
                request.cwd,
                request.env_map,
